function _buildLogsQS(params) {
  const keyMap = {
    startDate: 'start_date',
    endDate: 'end_date',
    username: 'username',
    project: 'project',
    model: 'model',
    provider: 'provider',
    direction: 'direction',
    sessionId: 'session_id',
    page: 'page',
    pageSize: 'page_size',
  }
  const parts = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${keyMap[k] || k}=${encodeURIComponent(v)}`)
  return parts.length ? `?${parts.join('&')}` : ''
}

