async def startup_event():
    start_background_services(APP_STOP_EVENT)
    # Resume chat turns interrupted by a previous shutdown/crash. Runs in the
    # API process too (not only in the background one): the per-turn flock
    # guarantees a single owner across processes.
    try:
        from codx.junior.chat.turn_recovery import start_turn_recovery

        start_turn_recovery(stop_event=APP_STOP_EVENT)
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to start the chat turn recovery worker: %s", ex)
    # Harness watchdog: monitors the orchestration worker heartbeat from the
    # API process and restarts the background process when it stalls with
    # active runs. Never started inside the background process itself.
    try:
        from codx.junior.harness.watchdog import start_harness_watchdog

        start_harness_watchdog(stop_event=APP_STOP_EVENT)
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to start the harness watchdog: %s", ex)
    # Zero-touch AI configuration: when the container is created with provider
    # environment variables (CODX_JUNIOR_AI_PROVIDER / CODX_JUNIOR_AI_API_KEY,
    # see codx/junior/bootstrap.py) create the provider and its models so a demo
    # installation is usable without opening the settings page. Idempotent: it
    # does nothing once a provider has been configured.
    try:
        from codx.junior.bootstrap import bootstrap_ai_from_env

        bootstrap_ai_from_env()
    except Exception as ex:  # pragma: no cover - defensive
        logger.exception("Failed to run the AI bootstrap: %s", ex)
    logger.info("FASTAPI startup")


